using System.ComponentModel;using System.Diagnostics;using System.IO;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using Microsoft.Win32;using ViewportCap.App.Services;using ViewportCap.Core;using ViewportCap.Encoding;using MessageBox=System.Windows.MessageBox;
namespace ViewportCap.App.Windows;
public partial class ReviewWindow:Window
{
 private readonly CaptureResult _result;private readonly AppSettings _settings;private readonly IExporter? _exporter;private readonly Action<string> _exported;private readonly DispatcherTimer _timer;private TimeSpan _duration;private bool _init=true,_playing,_busy,_deleted;private CancellationTokenSource? _cts;
  public ReviewWindow(CaptureResult result,AppSettings settings,IExporter? exporter,Action<string> exported){InitializeComponent();_result=result;_settings=settings;_exporter=exporter;_exported=exported;_duration=result.Duration>TimeSpan.FromMilliseconds(250)?result.Duration:TimeSpan.FromSeconds(1);FormatBox.ItemsSource=Enum.GetValues<OutputFormat>();FormatBox.SelectedItem=settings.DefaultFormat;QualityBox.ItemsSource=Enum.GetValues<QualityPreset>();QualityBox.SelectedItem=QualityPreset.Balanced;ScaleBox.ItemsSource=Enum.GetValues<ScalePreset>();ScaleBox.SelectedItem=settings.DefaultFormat==OutputFormat.Gif?ScalePreset.Fit960:ScalePreset.Percent100;FpsBox.ItemsSource=settings.DefaultFormat==OutputFormat.Gif?new[]{10,15,20}:new[]{15,30};FpsBox.SelectedItem=settings.DefaultFormat==OutputFormat.Gif?15:30;KeepAudioBox.IsChecked=result.HasAudio;KeepAudioBox.IsEnabled=result.HasAudio;if(!result.HasAudio)KeepAudioBox.Content="Silent recording";StartSlider.Maximum=EndSlider.Maximum=_duration.TotalSeconds;EndSlider.Value=_duration.TotalSeconds;UpdateTimes();if(exporter==null){FormatBox.ItemsSource=new[]{OutputFormat.Mp4};FormatBox.SelectedItem=OutputFormat.Mp4;QualityBox.IsEnabled=false;FpsBox.IsEnabled=false;ScaleBox.IsEnabled=false;StartSlider.IsEnabled=false;EndSlider.IsEnabled=false;KeepAudioBox.IsEnabled=false;KeepAudioBox.IsChecked=result.HasAudio;StatusText.Text="FFmpeg not found; untrimmed MP4 only.";}_init=false;Preview.Source=new Uri(result.FilePath);SourceInitialized+=(_,_)=>WindowAffinity.ExcludeFromCapture(this);Closing+=OnClosing;_timer=new(){Interval=TimeSpan.FromMilliseconds(100)};_timer.Tick+=(_,_)=>{if(_playing&&Preview.Position>=TimeSpan.FromSeconds(EndSlider.Value))Preview.Position=TimeSpan.FromSeconds(StartSlider.Value);};_timer.Start();Closed+=(_,_)=>_timer.Stop();}
  public void CancelExport(){_cts?.Cancel();}
  private void Preview_MediaOpened(object s,RoutedEventArgs e){if(Preview.NaturalDuration.HasTimeSpan){_duration=Preview.NaturalDuration.TimeSpan;StartSlider.Maximum=EndSlider.Maximum=_duration.TotalSeconds;EndSlider.Value=_duration.TotalSeconds;UpdateTimes();}Preview.Pause();}
  private void Preview_MediaFailed(object s,ExceptionRoutedEventArgs e){StatusText.Text="Preview unavailable. Timecode trimming remains available.";PlayButton.IsEnabled=false;OpenPreviewButton.Visibility=Visibility.Visible;}
  private void OpenPreview_Click(object s,RoutedEventArgs e){Process.Start(new ProcessStartInfo{FileName=_result.FilePath,UseShellExecute=true});}
 private void TrimChanged(object s,RoutedPropertyChangedEventArgs<double> e){if(_init)return;if(senderIsStart(s)&&StartSlider.Value>EndSlider.Value-.25)EndSlider.Value=Math.Min(EndSlider.Maximum,StartSlider.Value+.25);if(s==EndSlider&&EndSlider.Value<StartSlider.Value+.25)StartSlider.Value=Math.Max(0,EndSlider.Value-.25);UpdateTimes();}
 private static bool senderIsStart(object s)=>s is Slider slider&&slider.Name=="StartSlider";private void UpdateTimes(){StartText.Text=TimeSpan.FromSeconds(StartSlider.Value).ToString(@"mm\:ss\.ff");EndText.Text=TimeSpan.FromSeconds(EndSlider.Value).ToString(@"mm\:ss\.ff");}
 private void Play_Click(object s,RoutedEventArgs e){if(_playing){Preview.Pause();_playing=false;PlayButton.Content="Play";}else{Preview.Position=TimeSpan.FromSeconds(StartSlider.Value);Preview.Play();_playing=true;PlayButton.Content="Pause";}}
 private void FormatChanged(object s,SelectionChangedEventArgs e){if(_init)return;var gif=FormatBox.SelectedItem is OutputFormat.Gif;FpsBox.ItemsSource=gif?new[]{10,15,20}:new[]{15,30};FpsBox.SelectedItem=gif?15:30;ScaleBox.SelectedItem=gif?ScalePreset.Fit960:ScalePreset.Percent100;}
 private async void Export_Click(object s,RoutedEventArgs e)=>await ExportAsync(null);private async void SaveAs_Click(object s,RoutedEventArgs e){if(FormatBox.SelectedItem is not OutputFormat f)return;var ext=ExportNaming.Extension(f).TrimStart('.');var d=new Microsoft.Win32.SaveFileDialog{Filter=$"{f} files (*.{ext})|*.{ext}",DefaultExt=ext,FileName=ExportNaming.BuildBaseName(DateTimeOffset.Now)+"."+ext};if(d.ShowDialog()==true)await ExportAsync(d.FileName);}
  private async Task ExportAsync(string? path){if(_busy)return;var r=BuildSettings();var errors=r.Validate();if(errors.Count>0){MessageBox.Show(string.Join(Environment.NewLine,errors));return;}if(r.Format==OutputFormat.Gif&&(r.TrimDuration>TimeSpan.FromSeconds(30)||r.SourceWidth>1280)&&MessageBox.Show("GIF may be large or slow. Continue?","viewport-cap",MessageBoxButton.YesNo)==MessageBoxResult.No)return;ExportPlan plan;try{plan=path==null?ExportPlanner.Create(r,DateTimeOffset.Now,File.Exists):ExportPlanner.CreateForPath(r,path);}catch(Exception ex){MessageBox.Show(ex.Message);return;}if(_exporter==null&&!plan.CopySource){MessageBox.Show("FFmpeg is required for this export.");return;}if(_exporter==null){try{var directory=Path.GetDirectoryName(plan.OutputPath);if(!string.IsNullOrWhiteSpace(directory))Directory.CreateDirectory(directory);File.Copy(r.SourcePath,plan.OutputPath,true);Complete(plan.OutputPath);}catch(Exception ex){FileLog.Error("MP4 copy failed.",ex);MessageBox.Show($"Export failed:\n\n{ex.Message}","viewport-cap");}return;}_busy=true;_cts=new();try{var result=await _exporter.ExportAsync(plan,new Progress<double>(p=>Progress.Value=p),_cts.Token);Complete(result.OutputPath);}catch(Exception ex){MessageBox.Show($"Export failed:\n{ex.Message}");}finally{_busy=false;_cts.Dispose();_cts=null;}}
 private ReviewSettings BuildSettings(){var start=TimeSpan.FromSeconds(StartSlider.Value);var end=TimeSpan.FromSeconds(EndSlider.Value);return new(){SourcePath=_result.FilePath,OutputDirectory=_settings.OutputFolder,Format=FormatBox.SelectedItem is OutputFormat f?f:OutputFormat.Mp4,Quality=QualityBox.SelectedItem is QualityPreset q?q:QualityPreset.Balanced,FrameRate=FpsBox.SelectedItem is int fps?fps:30,Scale=ScaleBox.SelectedItem is ScalePreset p?p:ScalePreset.Percent100,TrimStart=start,TrimEnd=end,HasAudio=_result.HasAudio,MuteAudio=KeepAudioBox.IsChecked!=true,SourceWidth=_result.Width,SourceHeight=_result.Height,SourceDuration=_duration};}
  private void Complete(string path){_deleted=true;_busy=false;TryDelete();_exported(path);Close();}private void Discard_Click(object s,RoutedEventArgs e){if(_busy)return;if(MessageBox.Show("Discard this recording?","viewport-cap",MessageBoxButton.YesNo)==MessageBoxResult.Yes){_deleted=true;TryDelete();Close();}}
  private void OnClosing(object? s,CancelEventArgs e){if(_deleted)return;if(_busy){if(MessageBox.Show("Cancel the export and close?","viewport-cap",MessageBoxButton.YesNo)==MessageBoxResult.Yes)_cts?.Cancel();e.Cancel=true;return;}if(!_deleted&&MessageBox.Show("Discard this recording?","viewport-cap",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)e.Cancel=true;else TryDelete();}
 private void TryDelete(){try{if(File.Exists(_result.FilePath))File.Delete(_result.FilePath);}catch(Exception ex){FileLog.Warn(ex.Message);}}
}
